from collections import Counter,deque
DIRS4=[(-1,0),(1,0),(0,-1),(0,1)]; DIRS8=DIRS4+[(-1,-1),(-1,1),(1,-1),(1,1)]
def solve(g, use_d8=True, fill_inside=True):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=set(); kept_cells=set(); boxes=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for dx,dy in DIRS4:
                        p_,q_=a+dx,b+dy
                        if 0<=p_<H and 0<=q_<W and g[p_][q_]==col and (p_,q_) not in seen:
                            seen.add((p_,q_)); q.append((p_,q_))
                if len(comp)>=2:
                    kept_cells.update(comp)
                    rs=[a for a,b in comp]; cs=[b for a,b in comp]
                    boxes.append((min(rs),max(rs),min(cs),max(cs)))
                    # also box interior (bg) cells get filled with 1 if requested
                    if fill_inside:
                        for a in range(min(rs),max(rs)+1):
                            for b in range(min(cs),max(cs)+1):
                                if g[a][b]==bg: kept_cells.add((a,b))
    out=[row[:] for row in g]
    for (i,j) in kept_cells:
        out[i][j]=1
    stray={(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg and (i,j) not in kept_cells}
    dirs=DIRS8 if use_d8 else DIRS4
    for (i,j) in stray:
        cnt=Counter()
        for dx,dy in dirs:
            p_,q_=i+dx,j+dy
            if 0<=p_<H and 0<=q_<W: cnt[g[p_][q_]]+=1
        dom=max(cnt.values())
        top=[c for c,nv in cnt.items() if nv==dom and c!=bg]
        out[i][j]=top[0] if top else bg
    return out,bg
